return [
  {
    json: {
      sitemapUrl: "https://epcb.vn/sitemap_collections_1.xml",
      collectionUrl: "https://epcb.vn/collections/make-by-epcb",
      productPathPrefix: "https://epcb.vn/products/",
      backendBaseUrl: "https://content.epcb2.espitek.com",
      apiKey: "2ce3e492f751281be113952bea6ea028bcbf2a2f3e9c94bc",
    },
  },
];

const rawValue = $json.data ?? $json.body ?? "";
const html =
  typeof rawValue === "string" ? rawValue : JSON.stringify(rawValue);

const config = $("Config - thay domain và key").first().json;
const collectionUrl = String(config.collectionUrl || "").trim();
const productPathPrefix = String(config.productPathPrefix || "").trim();

if (!collectionUrl || !productPathPrefix) {
  throw new Error(
    "Thiếu collectionUrl hoặc productPathPrefix trong node cấu hình.",
  );
}

const decodeHtml = (value) =>
  String(value || "")
    .replace(/\\/g, "/")
    .replace(/&amp;/gi, "&")
    .replace(/&quot;/gi, '"')
    .replace(/&#39;|&apos;/gi, "'")
    .replace(/&lt;/gi, "<")
    .replace(/&gt;/gi, ">");

const parseHttpUrl = (value, fallbackOrigin) => {
  let raw = decodeHtml(value).trim();

  if (raw.startsWith("//")) raw = "https:" + raw;
  if (!/^https?:\/\//i.test(raw)) {
    if (!fallbackOrigin) return null;
    raw = raw.startsWith("/")
      ? fallbackOrigin + raw
      : fallbackOrigin + "/" + raw;
  }

  const match = raw.match(
    /^(https?):\/\/([^/?#]+)(\/[^?#]*)?(?:[?#].*)?$/i,
  );
  if (!match) return null;

  const origin =
    match[1].toLowerCase() + "://" + match[2].toLowerCase();
  const pathname = (match[3] || "/").replace(/\/{2,}/g, "/");

  return {
    origin,
    pathname,
    href: origin + pathname,
  };
};

const collection = parseHttpUrl(collectionUrl);
const productPrefix = parseHttpUrl(
  productPathPrefix,
  collection?.origin,
);

if (!collection || !productPrefix) {
  throw new Error(
    "collectionUrl hoặc productPathPrefix không hợp lệ.",
  );
}

const allowedOrigin = productPrefix.origin;
const allowedPath = productPrefix.pathname.endsWith("/")
  ? productPrefix.pathname
  : productPrefix.pathname + "/";

const candidates = [];

const collectMatches = (regex) => {
  for (const match of html.matchAll(regex)) {
    if (match[1]) candidates.push(decodeHtml(match[1]).trim());
  }
};

collectMatches(/href\s*=\s*["']([^"']+)["']/gi);
collectMatches(/href\s*=\s*([^\s>]+)/gi);
collectMatches(/(?:["']|\x22)([^"'<>\s]*\/products\/[^"'<>\s?#]*)/gi);

const productUrls = [];

for (const candidate of candidates) {
  const productUrl = parseHttpUrl(candidate, collection.origin);

  if (
    productUrl &&
    productUrl.origin === allowedOrigin &&
    productUrl.pathname.startsWith(allowedPath) &&
    productUrl.pathname.slice(allowedPath.length).trim() !== ""
  ) {
    productUrls.push(productUrl.href.replace(/\/$/, ""));
  }
}

const uniqueUrls = [...new Set(productUrls)];

if (!uniqueUrls.length) {
  throw new Error(
    "Không tìm thấy link sản phẩm. htmlLength=" +
      html.length +
      ", collectionUrl=" +
      collectionUrl +
      ", productPathPrefix=" +
      productPathPrefix,
  );
}

return uniqueUrls.map((productUrl) => ({
  json: {
    product_url: productUrl,
  },
}));

const sourceUrl = String(
  $("Lấy URL sản phẩm").item.json.product_url ||
    $json.product_url ||
    "",
).trim();

const rawProduct = $json.data ?? $json.body ?? $json;
let product = rawProduct;

if (typeof rawProduct === "string") {
  try {
    product = JSON.parse(rawProduct);
  } catch {
    throw new Error("Shopify Product JSON không hợp lệ: " + sourceUrl);
  }
}

const decode = (value) =>
  String(value || "")
    .replace(/&amp;/g, "&")
    .replace(/&quot;/g, '"')
    .replace(/&#39;|&apos;/g, "'")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .trim();

const strip = (value) =>
  decode(String(value || "").replace(/<[^>]+>/g, " ").replace(/\s+/g, " "));

const resolveHttpUrl = (value) => {
  let raw = decode(value);

  if (!raw) return "";
  if (raw.startsWith("//")) return "https:" + raw;
  return /^https?:\/\//i.test(raw) ? raw : "";
};

const title = strip(product.title || product.pagetitle || sourceUrl);
const description = strip(
  product.description || product.content || product.metadescription || "",
);

const imageValues = [];

const addImages = (value) => {
  if (Array.isArray(value)) {
    value.forEach(addImages);
    return;
  }

  if (typeof value === "string") {
    imageValues.push(resolveHttpUrl(value));
    return;
  }

  if (value && typeof value === "object") {
    addImages(
      value.src ||
        value.url ||
        value.featured_image ||
        value.preview_image?.src ||
        value.preview_image?.url,
    );
  }
};

addImages(product.images);
addImages(product.featured_image);
addImages(product.media);

const images = [
  ...new Set(imageValues.filter((url) => /^https?:\/\//i.test(url))),
]
  .slice(0, 30)
  .map((url, index) => ({
    url,
    alt: title,
    sortOrder: index,
  }));

const specificationParts = [
  product.vendor ? "Thương hiệu: " + strip(product.vendor) : "",
  product.type ? "Loại: " + strip(product.type) : "",
  Array.isArray(product.tags) && product.tags.length
    ? "Tags: " + product.tags.map(strip).join(", ")
    : "",
  Array.isArray(product.options) && product.options.length
    ? product.options
        .map((option) => {
          const values = Array.isArray(option.values)
            ? option.values.join(", ")
            : option.values || "";
          return option.name ? option.name + ": " + values : "";
        })
        .filter(Boolean)
        .join("\n")
    : "",
]
  .filter(Boolean)
  .join("\n");

return {
  json: {
    sourceUrl,
    canonicalUrl: sourceUrl,
    productName: title.slice(0, 300),
    description: description.slice(0, 10000),
    specifications: specificationParts.slice(0, 10000),
    category: strip(product.type || ""),
    images,
  },
};
